#!/usr/bin/env node
/**
 * One-off seed script — creates the 8 uiCopy entries for the login drawer (SFCC-742).
 *
 * Usage:
 *   node scripts/contentful/seedLoginDrawerUiCopy.mjs --target dev
 *
 * Targets a single Contentful environment. Defaults to 'dev' if --target is omitted.
 * Skips any entry whose key already exists in the target environment (safe to re-run).
 * Entries are created AND published in one pass.
 *
 * Required env vars (from .env via `npm run env -- init`):
 *   CONTENTFUL_MANAGEMENT_TOKEN
 *   CONTENTFUL_SPACE_ID
 */

import { checkEnv, createClient, log } from './setup/_shared.mjs';

const args = process.argv.slice(2);
const getArg = (flag) => {
  const i = args.indexOf(flag);
  return i !== -1 ? args[i + 1] : null;
};

const rawTarget = getArg('--target');
if (rawTarget === undefined) {
  // --target flag was present but no value followed it
  console.error('Error: --target requires a value, e.g. --target dev');
  process.exit(1);
}
const TARGET = rawTarget ?? 'dev';

checkEnv(['CONTENTFUL_MANAGEMENT_TOKEN', 'CONTENTFUL_SPACE_ID']);

/** @type {{ key: string; title: string; value: string; description: string }[]} */
const ENTRIES = [
  {
    key: 'login.drawer.email',
    title: 'Login Drawer — Email Input Label',
    value: 'Email',
    description: 'Label for the email address input field in the login drawer.',
  },
  {
    key: 'login.drawer.sendCode',
    title: 'Login Drawer — Send Code Button',
    value: 'Send code',
    description: 'CTA button label that triggers the passwordless email code in the login drawer.',
  },
  {
    key: 'login.drawer.signInWithApple',
    title: 'Login Drawer — Sign in with Apple',
    value: 'Sign in with Apple',
    description: 'Label for the Apple IDP social sign-in button in the login drawer.',
  },
  {
    key: 'login.drawer.signInWithGoogle',
    title: 'Login Drawer — Sign in with Google',
    value: 'Sign in with Google',
    description: 'Label for the Google IDP social sign-in button in the login drawer.',
  },
  {
    key: 'login.drawer.createAccount.heading',
    title: 'Login Drawer — Create Account Heading',
    value: 'New to Zimmermann?',
    description: 'Heading above the create account section at the bottom of the login drawer.',
  },
  {
    key: 'login.drawer.createAccount.body',
    title: 'Login Drawer — Create Account Body',
    value: 'Join for exclusive offers, early access and a more personal experience.',
    description: 'Body copy below the create account heading in the login drawer.',
  },
  {
    key: 'login.drawer.createAccount.cta',
    title: 'Login Drawer — Create Account CTA',
    value: 'Create an account',
    description: 'Button label for the create account action in the login drawer.',
  },
  {
    key: 'login.drawer.wishlist.description',
    title: 'Login Drawer — Wishlist Description',
    value: 'You must log in or create an account to add items to your wishlist.',
    description:
      'Descriptive text shown at the top of the login drawer when triggered from a wishlist action.',
  },
];

async function main() {
  const client = createClient();

  log.section(`Seeding ${ENTRIES.length} uiCopy entries → environment: ${TARGET}`);

  // Fetch all existing uiCopy entries across pages before duplicate checks.
  // contentful-management paginates at 1,000 — a single request may miss entries.
  const existing = [];
  let skip = 0;
  let total = Infinity;
  while (existing.length < total) {
    const page = await client.entry.getMany({
      environmentId: TARGET,
      query: { content_type: 'uiCopy', limit: 1000, skip },
    });
    total = page.total;
    existing.push(...page.items);
    skip += page.items.length;
    if (page.items.length === 0) break; // guard against a zero-item page to prevent infinite loop
  }

  // Map from uiCopy key → full entry object so we can inspect sys.publishedVersion below.
  const existingEntryMap = new Map(
    existing
      .map((e) => [e.fields?.key?.['en'], e])
      .filter(([key]) => Boolean(key)),
  );

  let created = 0;
  let skipped = 0;
  let published = 0;

  for (const entry of ENTRIES) {
    const existingEntry = existingEntryMap.get(entry.key);
    if (existingEntry) {
      if (existingEntry.sys.publishedVersion == null) {
        // Entry exists as a draft — publish it now so it is available to the app.
        await client.entry.publish(
          { environmentId: TARGET, entryId: existingEntry.sys.id },
          { sys: existingEntry.sys },
        );
        log.success(`${entry.key} — draft published`);
        published++;
      } else {
        log.skip(`${entry.key} — already published, skipping`);
        skipped++;
      }
      continue;
    }

    const created_entry = await client.entry.create(
      { environmentId: TARGET, contentTypeId: 'uiCopy' },
      {
        fields: {
          title: { 'en': entry.title },
          key: { 'en': entry.key },
          value: { 'en': entry.value },
          description: { 'en': entry.description },
        },
      },
    );

    await client.entry.publish(
      { environmentId: TARGET, entryId: created_entry.sys.id },
      { sys: created_entry.sys },
    );

    log.success(`${entry.key}`);
    created++;
  }

  log.section('Done');
  log.info(`Created and published: ${created}`);
  if (published) log.info(`Draft entries published: ${published}`);
  if (skipped) log.info(`Skipped (already published): ${skipped}`);
}

main().catch((err) => {
  log.error(err.message ?? String(err));
  process.exit(1);
});

